const pharmacies=[['A','Apotheke A · Demo','Bad Vilbel','Rhein-Main Ost',45],['B','Apotheke B · Demo','Frankfurt','Rhein-Main Ost',30],['C','Apotheke C · Demo','Hanau','Rhein-Main Ost',30],['A','Apotheke D · Demo','Offenbach','Rhein-Main Süd',30],['B','Apotheke E · Demo','Darmstadt','Rhein-Main Süd',45],['C','Apotheke F · Demo','Mainz','Rhein-Main West',30],['A','Apotheke G · Demo','Wiesbaden','Rhein-Main West',30],['B','Apotheke H · Demo','Gelnhausen','Rhein-Main Ost',30]];const title={today:'Deine Tour. Auf den Punkt.',round:'Verkaufsrunde',pharmacies:'Apotheken',settings:'Planungsregeln'};document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{document.querySelectorAll('nav button,.view').forEach(e=>e.classList.remove('active'));b.classList.add('active');document.getElementById(b.dataset.view).classList.add('active');document.getElementById('title').textContent=title[b.dataset.view]});const list=document.getElementById('pharmacy-list');function render(q=''){list.innerHTML=pharmacies.filter(p=>p.join(' ').toLowerCase().includes(q.toLowerCase())).map(p=>`<article><b class="priority">${p[0]}</b><div><strong>${p[1]}</strong><small>Musterstraße · ${p[2]}</small></div><span>${p[3]}</span><b>${p[4]} Min.</b></article>`).join('')}render();document.getElementById('search').oninput=e=>render(e.target.value);document.getElementById('optimise').onclick=()=>{document.getElementById('optimised').hidden=false;document.getElementById('optimise').textContent='✓ Runde aktualisiert'};['homebase','duration','capacity','overnight'].forEach(id=>{const el=document.getElementById(id),saved=localStorage.getItem('rp-'+id);if(saved!==null){if(el.type==='checkbox')el.checked=saved==='true';else el.value=saved}el.onchange=()=>localStorage.setItem('rp-'+id,el.type==='checkbox'?el.checked:el.value)});if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js');
